CREATE FUNCTION chalk_router.acquire_quota(p_actions jsonb, p_permit_id uuid, p_lease_ttl_seconds bigint, p_reservation_ttl_seconds bigint, p_environment_id text DEFAULT NULL::text, p_event_id uuid DEFAULT NULL::uuid, p_failed_amount bigint DEFAULT NULL::bigint) RETURNS TABLE(allowed boolean, needs_finish boolean, has_concurrency boolean, retry_after_ms bigint, rejected_source text, rejected_meter text, rejected_limit bigint)
    LANGUAGE plpgsql
    SET lock_timeout TO '1s'
    AS $$
DECLARE
    action RECORD;
    state_row RECORD;
    v_now TIMESTAMPTZ := clock_timestamp();
    v_rejected BOOLEAN := false;
    v_needs_finish BOOLEAN := false;
    v_has_concurrency BOOLEAN := false;
    v_retry_ms BIGINT := 0;
    v_policy_retry_ms BIGINT;
    v_refilled NUMERIC;
    v_expired BIGINT;
    v_rejected_source TEXT;
    v_rejected_meter TEXT;
    v_rejected_limit BIGINT;
BEGIN
    IF (p_environment_id IS NULL) <> (p_event_id IS NULL) THEN
        RAISE EXCEPTION 'background ownership requires both environment and event';
    END IF;
    IF p_event_id IS NOT NULL THEN
        PERFORM 1 FROM chalk_router.background_response_jobs
        WHERE environment_id = p_environment_id AND event_id = p_event_id
          AND phase = 'submitting' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'background submission intent is missing'; END IF;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_actions) AS item
                   WHERE item->>'environment_id' IS DISTINCT FROM p_environment_id)
        THEN RAISE EXCEPTION 'background ownership crossed an environment boundary'; END IF;
    END IF;
    IF jsonb_typeof(p_actions) <> 'array' THEN
        RAISE EXCEPTION 'quota actions must be a JSON array';
    END IF;

    IF (
        SELECT count(*) <> count(DISTINCT item.policy_id)
        FROM jsonb_to_recordset(p_actions) AS item(policy_id TEXT)
    ) THEN
        RAISE EXCEPTION 'quota actions contain duplicate policy ids';
    END IF;

    INSERT INTO chalk_router.quota_states
        (policy_id, balance, updated_at, window_start, used_amount, active_count)
    SELECT item.policy_id,
           CASE WHEN item.algorithm = 'token_bucket' THEN item.burst::NUMERIC END,
           CASE WHEN item.algorithm = 'token_bucket' THEN v_now END,
           CASE WHEN item.algorithm = 'fixed_window' THEN item.window_start END,
           0,
           0
    FROM jsonb_to_recordset(p_actions) AS item(
        policy_id TEXT,
        algorithm TEXT,
        burst BIGINT,
        window_start TIMESTAMPTZ
    )
    ORDER BY item.policy_id
    ON CONFLICT (policy_id) DO NOTHING;
    FOR action IN
        SELECT *
        FROM jsonb_to_recordset(p_actions) AS item(
            policy_id TEXT,
            source TEXT,
            algorithm TEXT,
            meter TEXT,
            limit_value BIGINT,
            burst BIGINT,
            amount BIGINT,
            window_start TIMESTAMPTZ,
            window_end TIMESTAMPTZ
        )
        ORDER BY policy_id
    LOOP
        IF action.limit_value <= 0 OR action.amount < 0 THEN
            RAISE EXCEPTION 'invalid compiled quota action for %', action.policy_id;
        END IF;

        SELECT * INTO state_row
        FROM chalk_router.quota_states
        WHERE policy_id = action.policy_id
        FOR UPDATE;

        IF action.algorithm = 'token_bucket' THEN
            IF action.burst IS NULL OR action.burst <= 0 THEN
                RAISE EXCEPTION 'token bucket % requires a positive burst', action.policy_id;
            END IF;
            v_refilled := LEAST(
                action.burst::NUMERIC,
                state_row.balance
                    + GREATEST(EXTRACT(EPOCH FROM (v_now - state_row.updated_at)), 0)
                    * action.limit_value::NUMERIC / 60
            );
            IF v_refilled < action.amount THEN
                v_policy_retry_ms := CEIL(
                    (action.amount - v_refilled) * 60000
                    / action.limit_value::NUMERIC
                )::BIGINT;
                v_rejected := true;
            ELSE
                v_policy_retry_ms := 0;
            END IF;
        ELSIF action.algorithm = 'fixed_window' THEN
            IF action.window_start IS NULL OR action.window_end IS NULL
               OR action.window_end <= action.window_start THEN
                RAISE EXCEPTION 'fixed window % requires valid boundaries', action.policy_id;
            END IF;
            IF state_row.window_start IS DISTINCT FROM action.window_start THEN
                UPDATE chalk_router.quota_states
                SET window_start = action.window_start, used_amount = 0
                WHERE policy_id = action.policy_id
                RETURNING * INTO state_row;
            END IF;
            IF action.amount > action.limit_value
               OR state_row.used_amount > action.limit_value - action.amount THEN
                v_policy_retry_ms := GREATEST(
                    CEIL(EXTRACT(EPOCH FROM (action.window_end - v_now)) * 1000)::BIGINT,
                    1
                );
                v_rejected := true;
            ELSE
                v_policy_retry_ms := 0;
            END IF;
        ELSIF action.algorithm = 'concurrency' THEN
            WITH expired AS (
                DELETE FROM chalk_router.quota_leases
                WHERE policy_id = action.policy_id AND expires_at <= v_now
                  AND background_event_id IS NULL
                RETURNING 1
            ) SELECT count(*) INTO v_expired FROM expired;
            IF v_expired > 0 THEN
                UPDATE chalk_router.quota_states
                SET active_count = GREATEST(active_count - v_expired, 0)
                WHERE policy_id = action.policy_id
                RETURNING * INTO state_row;
            END IF;
            v_needs_finish := true;
            v_has_concurrency := true;
            IF state_row.active_count >= action.limit_value THEN
                SELECT COALESCE(
                    CEIL(EXTRACT(EPOCH FROM (MIN(expires_at) - v_now)) * 1000)::BIGINT,
                    1000
                ) INTO v_policy_retry_ms
                FROM chalk_router.quota_leases
                WHERE policy_id = action.policy_id;
                v_policy_retry_ms := GREATEST(v_policy_retry_ms, 1);
                v_rejected := true;
            ELSE
                v_policy_retry_ms := 0;
            END IF;
        ELSE
            RAISE EXCEPTION 'unsupported quota algorithm %', action.algorithm;
        END IF;

        IF action.meter = 'tokens' THEN
            v_needs_finish := true;
        END IF;

        IF v_policy_retry_ms >= v_retry_ms AND v_rejected THEN
            v_retry_ms := GREATEST(v_policy_retry_ms, 1);
            v_rejected_source := action.source;
            v_rejected_meter := action.meter;
            v_rejected_limit := action.limit_value;
        END IF;
    END LOOP;

    IF v_rejected THEN
        -- Rejected acquisitions still persist refill, but never deduct any
        -- action. Successful acquisitions perform this write with deduction.
        UPDATE chalk_router.quota_states AS state
        SET balance = LEAST(item.burst::NUMERIC,
                state.balance + GREATEST(EXTRACT(EPOCH FROM (v_now - state.updated_at)), 0)
                * item.limit_value::NUMERIC / 60),
            updated_at = v_now
        FROM jsonb_to_recordset(p_actions) AS item(
            policy_id TEXT, algorithm TEXT, burst BIGINT, limit_value BIGINT)
        WHERE state.policy_id = item.policy_id AND item.algorithm = 'token_bucket';
        RETURN QUERY SELECT false, false, false, v_retry_ms,
                            v_rejected_source, v_rejected_meter,
                            v_rejected_limit;
        RETURN;
    END IF;

    FOR action IN
        SELECT *
        FROM jsonb_to_recordset(p_actions) AS item(
            policy_id TEXT,
            source TEXT,
            algorithm TEXT,
            meter TEXT,
            limit_value BIGINT,
            burst BIGINT,
            amount BIGINT,
            window_start TIMESTAMPTZ,
            window_end TIMESTAMPTZ
        )
        ORDER BY policy_id
    LOOP
        IF action.algorithm = 'token_bucket' THEN
            UPDATE chalk_router.quota_states
            SET balance = LEAST(action.burst::NUMERIC,
                    balance + GREATEST(EXTRACT(EPOCH FROM (v_now - updated_at)), 0)
                    * action.limit_value::NUMERIC / 60) - action.amount,
                updated_at = v_now
            WHERE policy_id = action.policy_id;
        ELSIF action.algorithm = 'fixed_window' THEN
            UPDATE chalk_router.quota_states
            SET used_amount = used_amount + action.amount
            WHERE policy_id = action.policy_id;
        ELSE
            UPDATE chalk_router.quota_states
            SET active_count = active_count + 1
            WHERE policy_id = action.policy_id;
            INSERT INTO chalk_router.quota_leases
                (policy_id, permit_id, expires_at, background_environment_id, background_event_id)
            VALUES (
                action.policy_id,
                p_permit_id,
                v_now + make_interval(secs => p_lease_ttl_seconds::INTEGER),
                p_environment_id,
                p_event_id
            );
        END IF;

        IF action.meter = 'tokens' THEN
            INSERT INTO chalk_router.quota_reservations
                (policy_id, permit_id, reserved_amount, window_start, expires_at,
                 background_environment_id, background_event_id,
                 algorithm, limit_value, burst, failed_amount)
            VALUES (
                action.policy_id,
                p_permit_id,
                action.amount,
                action.window_start,
                CASE WHEN action.algorithm = 'fixed_window'
                     THEN LEAST(
                         action.window_end,
                         v_now + make_interval(secs => p_reservation_ttl_seconds::INTEGER)
                     )
                     ELSE v_now + make_interval(secs => p_reservation_ttl_seconds::INTEGER)
                END,
                p_environment_id,
                p_event_id,
                CASE WHEN p_event_id IS NOT NULL THEN action.algorithm END,
                CASE WHEN p_event_id IS NOT NULL THEN action.limit_value END,
                CASE WHEN p_event_id IS NOT NULL THEN action.burst END,
                CASE WHEN p_event_id IS NOT NULL THEN p_failed_amount END
            );
        END IF;
    END LOOP;

    RETURN QUERY SELECT true, v_needs_finish, v_has_concurrency,
                        0::BIGINT, NULL::TEXT, NULL::TEXT, NULL::BIGINT;
END;
$$;


--
-- Name: acquire_request_and_route_quota(jsonb, jsonb, uuid, uuid, bigint, bigint, bigint); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.acquire_request_and_route_quota(p_request_actions jsonb, p_route_actions jsonb, p_request_permit_id uuid, p_route_permit_id uuid, p_lease_ttl_seconds bigint, p_reservation_ttl_seconds bigint, p_route_failed_amount bigint) RETURNS TABLE(request_decision jsonb, route_decision jsonb, route_error text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_now TIMESTAMPTZ := clock_timestamp();
    v_request RECORD;
    v_route RECORD;
BEGIN
    IF jsonb_typeof(p_request_actions) <> 'array'
       OR jsonb_typeof(p_route_actions) <> 'array' THEN
        RAISE EXCEPTION 'quota actions must be JSON arrays';
    END IF;
    INSERT INTO chalk_router.quota_states
        (policy_id, balance, updated_at, window_start, used_amount, active_count)
    SELECT item.policy_id,
           CASE WHEN item.algorithm = 'token_bucket' THEN item.burst::NUMERIC END,
           CASE WHEN item.algorithm = 'token_bucket' THEN v_now END,
           CASE WHEN item.algorithm = 'fixed_window' THEN item.window_start END,
           0, 0
    FROM (
        SELECT DISTINCT ON (policy_id) *
        FROM jsonb_to_recordset(p_request_actions || p_route_actions) AS a(
            policy_id TEXT, algorithm TEXT, burst BIGINT, window_start TIMESTAMPTZ)
        ORDER BY policy_id
    ) AS item
    ORDER BY item.policy_id
    ON CONFLICT (policy_id) DO NOTHING;

    PERFORM 1 FROM chalk_router.quota_states
    WHERE policy_id IN (
        SELECT item->>'policy_id'
        FROM jsonb_array_elements(p_request_actions || p_route_actions) AS item
    ) ORDER BY policy_id FOR UPDATE;

    SELECT * INTO v_request FROM chalk_router.acquire_quota(
        p_request_actions, p_request_permit_id,
        p_lease_ttl_seconds, p_reservation_ttl_seconds);
    IF NOT v_request.allowed THEN
        RETURN QUERY SELECT to_jsonb(v_request), NULL::JSONB, NULL::TEXT;
        RETURN;
    END IF;
    BEGIN
        SELECT * INTO v_route FROM chalk_router.acquire_quota(
            p_route_actions, p_route_permit_id,
            p_lease_ttl_seconds, p_reservation_ttl_seconds,
            NULL::TEXT, NULL::UUID, p_route_failed_amount);
    EXCEPTION WHEN OTHERS THEN
        -- Roll back only the route phase. A definite route backend failure
        -- must retain the request charge, matching separate admissions. Query
        -- cancellation still aborts normally; clients never replay admission.
        RETURN QUERY SELECT to_jsonb(v_request), NULL::JSONB, SQLSTATE;
        RETURN;
    END;
    RETURN QUERY SELECT to_jsonb(v_request), to_jsonb(v_route), NULL::TEXT;
END;
$$;


--
-- Name: cleanup_quota_runtime(bigint); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.cleanup_quota_runtime(p_batch_size bigint) RETURNS TABLE(reservations_deleted bigint, leases_deleted bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reservation_candidates JSONB;
    v_lease_candidates JSONB;
    v_reservations BIGINT;
    v_leases BIGINT := 0;
    removed RECORD;
BEGIN
    -- Freeze each bounded batch before taking locks. Re-running a candidate
    -- query afterward could include a newly expired policy we did not lock.
    SELECT COALESCE(jsonb_agg(candidate), '[]'::JSONB)
    INTO v_reservation_candidates FROM (
        SELECT policy_id, permit_id FROM chalk_router.quota_reservations
        WHERE expires_at <= clock_timestamp() AND background_event_id IS NULL
        ORDER BY expires_at, policy_id, permit_id LIMIT GREATEST(p_batch_size, 0)
    ) AS candidate;
    SELECT COALESCE(jsonb_agg(candidate), '[]'::JSONB)
    INTO v_lease_candidates FROM (
        SELECT policy_id, permit_id FROM chalk_router.quota_leases
        WHERE expires_at <= clock_timestamp() AND background_event_id IS NULL
        ORDER BY policy_id, expires_at, permit_id LIMIT GREATEST(p_batch_size, 0)
    ) AS candidate;

    -- Shared hierarchy: background job (when present), all states in policy
    -- order, then receipts. finish_quota already follows this since 0025.
    PERFORM 1 FROM chalk_router.quota_states
    WHERE policy_id IN (
        SELECT policy_id FROM jsonb_to_recordset(v_reservation_candidates) AS c(policy_id TEXT)
        UNION
        SELECT policy_id FROM jsonb_to_recordset(v_lease_candidates) AS c(policy_id TEXT)
    ) ORDER BY policy_id FOR UPDATE;

    WITH deleted AS (
        DELETE FROM chalk_router.quota_reservations AS r
        USING jsonb_to_recordset(v_reservation_candidates) AS c(policy_id TEXT, permit_id UUID)
        WHERE r.policy_id = c.policy_id AND r.permit_id = c.permit_id
          AND r.expires_at <= clock_timestamp() AND r.background_event_id IS NULL
        RETURNING 1
    ) SELECT count(*) INTO v_reservations FROM deleted;

    FOR removed IN
        WITH deleted AS (
            DELETE FROM chalk_router.quota_leases AS l
            USING jsonb_to_recordset(v_lease_candidates) AS c(policy_id TEXT, permit_id UUID)
            WHERE l.policy_id = c.policy_id AND l.permit_id = c.permit_id
              AND l.expires_at <= clock_timestamp() AND l.background_event_id IS NULL
            RETURNING l.policy_id
        ) SELECT policy_id, count(*) AS n FROM deleted GROUP BY policy_id
    LOOP
        UPDATE chalk_router.quota_states
        SET active_count = GREATEST(active_count - removed.n, 0)
        WHERE policy_id = removed.policy_id;
        v_leases := v_leases + removed.n;
    END LOOP;
    RETURN QUERY SELECT v_reservations, v_leases;
END;
$$;


--
-- Name: finish_background_response_quota(text, uuid, bigint, boolean); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.finish_background_response_quota(p_environment_id text, p_event_id uuid, p_actual_amount bigint, p_failed boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE owned_permit RECORD;
BEGIN
    PERFORM 1 FROM chalk_router.background_response_jobs
    WHERE environment_id = p_environment_id AND event_id = p_event_id FOR UPDATE;
    PERFORM 1 FROM chalk_router.quota_states
    WHERE policy_id IN (
        SELECT policy_id FROM chalk_router.quota_reservations
        WHERE background_environment_id = p_environment_id AND background_event_id = p_event_id
        UNION
        SELECT policy_id FROM chalk_router.quota_leases
        WHERE background_environment_id = p_environment_id AND background_event_id = p_event_id
    ) ORDER BY policy_id FOR UPDATE;
    FOR owned_permit IN
        SELECT permit_id FROM chalk_router.quota_reservations
        WHERE background_environment_id = p_environment_id AND background_event_id = p_event_id
        UNION
        SELECT permit_id FROM chalk_router.quota_leases
        WHERE background_environment_id = p_environment_id AND background_event_id = p_event_id
        ORDER BY permit_id
    LOOP
        PERFORM chalk_router.finish_quota('[]', owned_permit.permit_id, p_actual_amount, p_failed);
    END LOOP;
END;
$$;


--
-- Name: finish_quota(jsonb, uuid, bigint, boolean); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.finish_quota(p_actions jsonb, p_permit_id uuid, p_actual_amount bigint, p_failed boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    reservation RECORD;
    state_row RECORD;
    lease_row RECORD;
    v_now TIMESTAMPTZ := clock_timestamp();
    v_refilled NUMERIC;
    v_actual BIGINT;
    v_excess BIGINT;
BEGIN
    PERFORM 1 FROM chalk_router.quota_states
    WHERE policy_id IN (
        SELECT policy_id FROM chalk_router.quota_reservations WHERE permit_id = p_permit_id
        UNION
        SELECT policy_id FROM chalk_router.quota_leases WHERE permit_id = p_permit_id
    ) ORDER BY policy_id FOR UPDATE;
    FOR reservation IN
        SELECT stored.policy_id, stored.reserved_amount, stored.window_start,
               CASE WHEN stored.background_event_id IS NOT NULL THEN stored.algorithm
                    ELSE action.algorithm END AS algorithm,
               CASE WHEN stored.background_event_id IS NOT NULL THEN stored.limit_value
                    ELSE action.limit_value END AS limit_value,
               CASE WHEN stored.background_event_id IS NOT NULL THEN stored.burst
                    ELSE action.burst END AS burst,
               CASE WHEN stored.background_event_id IS NOT NULL THEN NULL
                    ELSE action.window_end END AS window_end,
               CASE WHEN p_failed AND stored.background_event_id IS NOT NULL
                    THEN stored.failed_amount ELSE p_actual_amount END AS actual_amount
        FROM chalk_router.quota_reservations AS stored
        LEFT JOIN jsonb_to_recordset(p_actions) AS action(
            policy_id TEXT, algorithm TEXT, limit_value BIGINT, burst BIGINT,
            window_end TIMESTAMPTZ
        ) ON action.policy_id = stored.policy_id
        WHERE stored.permit_id = p_permit_id
        ORDER BY stored.policy_id
    LOOP
        IF reservation.actual_amount IS NULL THEN CONTINUE; END IF;
        v_actual := GREATEST(reservation.actual_amount, 0);
        v_excess := GREATEST(v_actual - reservation.reserved_amount, 0);
        SELECT * INTO state_row FROM chalk_router.quota_states
        WHERE policy_id = reservation.policy_id;
        IF NOT FOUND THEN CONTINUE; END IF;
        IF reservation.algorithm = 'token_bucket' THEN
            v_refilled := LEAST(
                reservation.burst::NUMERIC,
                state_row.balance
                    + GREATEST(EXTRACT(EPOCH FROM (v_now - state_row.updated_at)), 0)
                    * reservation.limit_value::NUMERIC / 60
            );
            UPDATE chalk_router.quota_states
            SET balance = LEAST(reservation.burst::NUMERIC,
                    v_refilled + reservation.reserved_amount - v_actual),
                updated_at = v_now
            WHERE policy_id = reservation.policy_id;
        ELSIF reservation.algorithm = 'fixed_window'
              AND state_row.window_start IS NOT DISTINCT FROM reservation.window_start THEN
            IF reservation.window_end IS NOT NULL AND reservation.window_end <= v_now THEN
                -- The admitting window closed and no admission has rolled the
                -- counter yet. Open the next window with the excess so the
                -- reset keeps it.
                UPDATE chalk_router.quota_states
                SET window_start = reservation.window_end, used_amount = v_excess
                WHERE policy_id = reservation.policy_id;
            ELSE
                UPDATE chalk_router.quota_states
                SET used_amount = LEAST(GREATEST(
                        used_amount::NUMERIC - reservation.reserved_amount + v_actual, 0
                    ), 9223372036854775807)::BIGINT
                WHERE policy_id = reservation.policy_id;
            END IF;
        ELSIF reservation.algorithm = 'fixed_window'
              AND state_row.window_start > reservation.window_start THEN
            -- A later admission already opened a newer window.
            UPDATE chalk_router.quota_states
            SET used_amount = LEAST(used_amount::NUMERIC + v_excess,
                    9223372036854775807)::BIGINT
            WHERE policy_id = reservation.policy_id;
        END IF;
    END LOOP;
    DELETE FROM chalk_router.quota_reservations WHERE permit_id = p_permit_id;
    FOR lease_row IN
        DELETE FROM chalk_router.quota_leases WHERE permit_id = p_permit_id RETURNING policy_id
    LOOP
        UPDATE chalk_router.quota_states SET active_count = GREATEST(active_count - 1, 0)
        WHERE policy_id = lease_row.policy_id;
    END LOOP;
END;
$$;


--
-- Name: finish_quota_usage(jsonb, bigint, uuid, timestamp with time zone, text, text, text, text, text, bigint, bigint, bigint, bigint, bigint, bigint, smallint, double precision); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.finish_quota_usage(p_grants jsonb, p_actual_amount bigint, p_event_id uuid, p_time timestamp with time zone, p_environment_id text, p_api_key_hash text, p_usage_pool_id text, p_connection_id text, p_model text, p_prompt_tokens bigint, p_completion_tokens bigint, p_cached_tokens bigint, p_cache_write_tokens bigint, p_reasoning_tokens bigint, p_total_tokens bigint, p_usage_source smallint, p_estimated_cost_usd double precision) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    grant_row RECORD;
    v_now TIMESTAMPTZ;
    v_actual BIGINT := GREATEST(p_actual_amount, 0);
BEGIN
    IF jsonb_typeof(p_grants) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'terminal grants must be an array';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_grants) AS grant_item,
                      jsonb_array_elements(grant_item->'actions') AS action
        WHERE action->>'environment_id' IS DISTINCT FROM p_environment_id
           OR grant_item->'background_owner' IS DISTINCT FROM 'null'::JSONB
    ) THEN
        RAISE EXCEPTION 'terminal accounting requires foreground grants in one environment';
    END IF;

    -- Receipt deletion, settlement, and usage insertion commit or roll back together.
    -- Insert before locking quota states: the insert needs no quota lock, so
    -- hot states are held only for settlement. Always settle receipts even when
    -- an earlier standalone insert wrote usage.
    INSERT INTO chalk_router.usage_events
        (event_id, time, environment_id, api_key_hash, usage_pool_id, connection_id, model,
         prompt_tokens, completion_tokens, cached_tokens, cache_write_tokens,
         reasoning_tokens, total_tokens, request_count, usage_source, estimated_cost_usd)
    VALUES (p_event_id, p_time, p_environment_id, p_api_key_hash, p_usage_pool_id,
            p_connection_id, p_model, p_prompt_tokens, p_completion_tokens,
            p_cached_tokens, p_cache_write_tokens, p_reasoning_tokens,
            p_total_tokens, 1, p_usage_source, p_estimated_cost_usd)
    ON CONFLICT (environment_id, event_id) DO NOTHING;

    -- Canonical union ordering prevents deadlocks across differently ordered grants.
    PERFORM 1 FROM chalk_router.quota_states
    WHERE policy_id IN (
        SELECT policy_id FROM chalk_router.quota_reservations
        WHERE permit_id IN (SELECT (item->>'permit_id')::UUID FROM jsonb_array_elements(p_grants) AS item)
        UNION
        SELECT policy_id FROM chalk_router.quota_leases
        WHERE permit_id IN (SELECT (item->>'permit_id')::UUID FROM jsonb_array_elements(p_grants) AS item)
    ) ORDER BY policy_id FOR UPDATE;

    FOR grant_row IN SELECT * FROM jsonb_to_recordset(p_grants) AS item(permit_id UUID, actions JSONB)
    LOOP
        -- Rust admissions validate uniqueness. Retain the old ordered behavior
        -- for direct SQL callers supplying duplicate actions as well.
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(grant_row.actions) AS action
                   GROUP BY action->>'policy_id' HAVING count(*) > 1) THEN
            PERFORM chalk_router.finish_quota(grant_row.actions, grant_row.permit_id, p_actual_amount, FALSE);
            CONTINUE;
        END IF;
        v_now := clock_timestamp();
        WITH reservations AS (
            DELETE FROM chalk_router.quota_reservations
            WHERE permit_id = grant_row.permit_id
            RETURNING *
        ), leases AS (
            DELETE FROM chalk_router.quota_leases
            WHERE permit_id = grant_row.permit_id
            RETURNING policy_id
        ), adjustments AS (
            SELECT stored.policy_id, stored.reserved_amount, stored.window_start,
                   CASE WHEN stored.background_event_id IS NOT NULL THEN stored.algorithm
                        ELSE action.algorithm END AS algorithm,
                   CASE WHEN stored.background_event_id IS NOT NULL THEN stored.limit_value
                        ELSE action.limit_value END AS limit_value,
                   CASE WHEN stored.background_event_id IS NOT NULL THEN stored.burst
                        ELSE action.burst END AS burst,
                   CASE WHEN stored.background_event_id IS NOT NULL THEN NULL
                        ELSE action.window_end END AS window_end,
                   GREATEST(v_actual - stored.reserved_amount, 0) AS excess
            FROM reservations AS stored
            LEFT JOIN jsonb_to_recordset(grant_row.actions) AS action(
                policy_id TEXT, algorithm TEXT, limit_value BIGINT, burst BIGINT,
                window_end TIMESTAMPTZ
            ) ON action.policy_id = stored.policy_id
        ), changes AS (
            SELECT COALESCE(a.policy_id, l.policy_id) AS policy_id,
                   a.reserved_amount, a.window_start, a.algorithm, a.limit_value,
                   a.burst, a.window_end, a.excess, l.policy_id IS NOT NULL AS release_lease
            FROM adjustments AS a FULL JOIN leases AS l USING (policy_id)
        )
        UPDATE chalk_router.quota_states AS state
        SET balance = CASE WHEN p_actual_amount IS NOT NULL AND c.algorithm = 'token_bucket'
                THEN LEAST(c.burst::NUMERIC,
                    LEAST(c.burst::NUMERIC, state.balance
                        + GREATEST(EXTRACT(EPOCH FROM (v_now - state.updated_at)), 0)
                        * c.limit_value::NUMERIC / 60)
                    + c.reserved_amount - v_actual)
                ELSE state.balance END,
            updated_at = CASE WHEN p_actual_amount IS NOT NULL AND c.algorithm = 'token_bucket'
                THEN v_now ELSE state.updated_at END,
            used_amount = CASE WHEN p_actual_amount IS NULL OR c.algorithm IS DISTINCT FROM 'fixed_window'
                THEN state.used_amount
                WHEN state.window_start IS NOT DISTINCT FROM c.window_start THEN
                    CASE WHEN c.window_end IS NOT NULL AND c.window_end <= v_now THEN c.excess
                         ELSE LEAST(GREATEST(state.used_amount::NUMERIC - c.reserved_amount + v_actual, 0),
                             9223372036854775807)::BIGINT END
                WHEN state.window_start > c.window_start
                    THEN LEAST(state.used_amount::NUMERIC + c.excess, 9223372036854775807)::BIGINT
                ELSE state.used_amount END,
            window_start = CASE WHEN p_actual_amount IS NOT NULL AND c.algorithm = 'fixed_window'
                    AND state.window_start IS NOT DISTINCT FROM c.window_start
                    AND c.window_end IS NOT NULL AND c.window_end <= v_now
                THEN c.window_end ELSE state.window_start END,
            active_count = CASE WHEN c.release_lease THEN GREATEST(state.active_count - 1, 0)
                ELSE state.active_count END
        FROM changes AS c WHERE state.policy_id = c.policy_id;
    END LOOP;
END;
$$;


--
-- Name: renew_quota(uuid, bigint); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.renew_quota(p_permit_id uuid, p_lease_ttl_seconds bigint) RETURNS void
    LANGUAGE sql
    AS $$
    UPDATE chalk_router.quota_leases
    SET expires_at = clock_timestamp()
        + make_interval(secs => p_lease_ttl_seconds::INTEGER)
    WHERE permit_id = p_permit_id;
$$;


--
-- Name: renew_quota(uuid, bigint, bigint); Type: FUNCTION; Schema: chalk_router; Owner: -
--

CREATE FUNCTION chalk_router.renew_quota(p_permit_id uuid, p_lease_ttl_seconds bigint, p_reservation_ttl_seconds bigint) RETURNS void
    LANGUAGE sql
    AS $$
    UPDATE chalk_router.quota_leases
    SET expires_at = clock_timestamp()
        + make_interval(secs => p_lease_ttl_seconds::INTEGER)
    WHERE permit_id = p_permit_id;
    UPDATE chalk_router.quota_reservations
    SET expires_at = clock_timestamp()
        + make_interval(secs => p_reservation_ttl_seconds::INTEGER)
    WHERE permit_id = p_permit_id AND background_event_id IS NULL;
$$;


