    connection_id text,
    upstream_response_id text,
    phase text NOT NULL,
    payload jsonb NOT NULL,
    next_poll_at timestamp with time zone NOT NULL,
    claim_owner uuid,
    claim_until timestamp with time zone,
    poll_attempts bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    last_error_code text,
    CONSTRAINT background_response_jobs_check CHECK (((phase <> ALL (ARRAY['active'::text, 'terminal'::text])) OR ((connection_id IS NOT NULL) AND (upstream_response_id IS NOT NULL)))),
    CONSTRAINT background_response_jobs_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT background_response_jobs_phase_check CHECK ((phase = ANY (ARRAY['submitting'::text, 'active'::text, 'terminal'::text, 'settled'::text, 'unresolved'::text]))),
    CONSTRAINT background_response_jobs_poll_attempts_check CHECK ((poll_attempts >= 0))
);


