    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    period text DEFAULT 'daily'::text NOT NULL,
    CONSTRAINT budget_limits_limit_kind_check CHECK ((limit_kind = ANY (ARRAY['tokens'::text, 'cost_micro_usd'::text]))),
    CONSTRAINT budget_limits_period_check CHECK ((period = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text]))),
    CONSTRAINT budget_limits_scope_check CHECK ((scope = ANY (ARRAY['usage_pool'::text, 'api_key'::text]))),
    CONSTRAINT budget_limits_window_type_check CHECK ((window_type = ANY (ARRAY['calendar'::text, 'rolling'::text])))
);


