);


--
-- Name: quota_reservations; Type: TABLE; Schema: chalk_router; Owner: -
--

CREATE TABLE chalk_router.quota_reservations (
    policy_id text NOT NULL,
    permit_id uuid NOT NULL,
    reserved_amount bigint NOT NULL,
    window_start timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    background_environment_id text,
    background_event_id uuid,
    algorithm text,
    limit_value bigint,
    burst bigint,
    failed_amount bigint,
    CONSTRAINT quota_reservations_background_settlement_check CHECK (((background_event_id IS NULL) OR ((algorithm IS NOT NULL) AND (algorithm = ANY (ARRAY['token_bucket'::text, 'fixed_window'::text])) AND (limit_value IS NOT NULL) AND (limit_value > 0) AND ((algorithm <> 'token_bucket'::text) OR ((burst IS NOT NULL) AND (burst > 0)))))),
    CONSTRAINT quota_reservations_failed_amount_check CHECK ((failed_amount >= 0)),
    CONSTRAINT quota_reservations_reserved_amount_check CHECK ((reserved_amount >= 0))
);


