    window_start timestamp with time zone,
    used_amount bigint DEFAULT 0 NOT NULL,
    active_count bigint DEFAULT 0 NOT NULL,
    CONSTRAINT quota_states_active_count_check CHECK ((active_count >= 0)),
    CONSTRAINT quota_states_used_amount_check CHECK ((used_amount >= 0))
);


