    limit_type text NOT NULL,
    limit_value bigint NOT NULL,
    scope text NOT NULL,
    scope_id text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    connection_id text,
    models text[] DEFAULT '{}'::text[] NOT NULL,
    burst_value bigint,
    CONSTRAINT rate_limits_burst_check CHECK (((burst_value IS NULL) OR (burst_value > 0))),
    CONSTRAINT rate_limits_concurrency_burst_check CHECK (((limit_type <> 'concurrent_requests'::text) OR (burst_value IS NULL))),
    CONSTRAINT rate_limits_models_require_connection_check CHECK (((connection_id IS NOT NULL) OR (cardinality(models) = 0))),
    CONSTRAINT rate_limits_scope_check CHECK ((scope = ANY (ARRAY['api_key'::text, 'usage_pool'::text]))),
    CONSTRAINT rate_limits_scope_id_check CHECK ((scope_id <> ''::text)),
    CONSTRAINT rate_limits_type_check CHECK ((limit_type = ANY (ARRAY['requests_per_minute'::text, 'tokens_per_minute'::text, 'concurrent_requests'::text]))),
    CONSTRAINT rate_limits_value_check CHECK ((limit_value > 0))
);


