--
-- Name: usage_events; Type: TABLE; Schema: chalk_router; Owner: -
--

CREATE TABLE chalk_router.usage_events (
    "time" timestamp with time zone NOT NULL,
    environment_id text NOT NULL,
    api_key_hash text NOT NULL,
    usage_pool_id text,
    provider text,
    model text,
    prompt_tokens bigint DEFAULT 0 NOT NULL,
    completion_tokens bigint DEFAULT 0 NOT NULL,
    cached_tokens bigint DEFAULT 0 NOT NULL,
    total_tokens bigint DEFAULT 0 NOT NULL,
    request_count bigint DEFAULT 0 NOT NULL,
    connection_id text,
    cache_write_tokens bigint DEFAULT 0 NOT NULL,
    reasoning_tokens bigint DEFAULT 0 NOT NULL,
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    usage_source smallint DEFAULT 3 NOT NULL,
    estimated_cost_usd double precision,
    CONSTRAINT ck_router_usage_source CHECK ((usage_source = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT ck_router_usage_token_invariants CHECK (((prompt_tokens >= 0) AND (completion_tokens >= 0) AND (cached_tokens >= 0) AND (cache_write_tokens >= 0) AND (reasoning_tokens >= 0) AND (total_tokens >= 0) AND (request_count >= 0) AND (cached_tokens <= prompt_tokens) AND (cache_write_tokens <= prompt_tokens) AND (reasoning_tokens <= completion_tokens))),
    CONSTRAINT usage_events_estimated_cost_usd_check CHECK ((estimated_cost_usd >= (0)::double precision))
);


